import { NextRequest, NextResponse } from "next/server";
import { rateLimit, getClientIp, sanitizeLine, tooLarge } from "@/lib/ratelimit";

const TELEGRAM_BOT_TOKEN = [REDACTED];
const TELEGRAM_CHAT_ID = process.env.TELEGRAM_CHAT_ID;

const MAX_BODY_BYTES = 10_000;

interface TelemetryPayload {
  instance_id: string;
  version: string;
  os: string;
  arch: string;
  uptime_secs: number;
  user_count: number;
  total_memories: number;
  storage_mb: number;
  features: {
    backups: boolean;
    production: boolean;
    zenoh: boolean;
  };
}

async function sendToTelegram(message: string) {
  if (!TELEGRAM_BOT_TOKEN || !TELEGRAM_CHAT_ID) {
    console.log("Telegram credentials missing, skipping notification");
    return;
  }

  try {
    const res = await fetch(
      `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          chat_id: TELEGRAM_CHAT_ID,
          text: message,
        }),
      }
    );
    const data = await res.json();
    if (!data.ok) {
      console.error("Telegram API error:", JSON.stringify(data));
    }
  } catch (err) {
    console.error("Telegram send error:", err);
  }
}

function formatUptime(secs: number): string {
  const days = Math.floor(secs / 86400);
  const hours = Math.floor((secs % 86400) / 3600);
  if (days > 0) return `${days}d ${hours}h`;
  const mins = Math.floor((secs % 3600) / 60);
  return hours > 0 ? `${hours}h ${mins}m` : `${mins}m`;
}

export async function POST(req: NextRequest) {
  const ip = getClientIp(req.headers);

  if (tooLarge(req.headers, MAX_BODY_BYTES)) {
    return NextResponse.json({ error: "Request too large" }, { status: 413 });
  }

  const ipLimit = rateLimit(`telemetry:${ip}`, 60, 3_600_000);
  if (!ipLimit.allowed) {
    return NextResponse.json(
      { error: "Too many requests" },
      { status: 429, headers: { "Retry-After": String(ipLimit.retryAfterSec) } }
    );
  }

  try {
    const payload: TelemetryPayload = await req.json();

    // Validate required fields
    if (!payload.instance_id || !payload.version) {
      return NextResponse.json(
        { error: "Missing required fields" },
        { status: 400 }
      );
    }

    // Sanitize: cap string lengths and strip newlines/control chars so
    // payload fields can't inject structure into the Telegram message
    const instanceId = sanitizeLine(payload.instance_id, 64).replace(/[^\w-]/g, "");
    const version = sanitizeLine(payload.version, 32);
    const os = sanitizeLine(payload.os || "unknown", 32);
    const arch = sanitizeLine(payload.arch || "unknown", 32);
    const uptimeSecs = Math.max(0, Number(payload.uptime_secs) || 0);
    const userCount = Math.max(0, Number(payload.user_count) || 0);
    const totalMemories = Math.max(0, Number(payload.total_memories) || 0);
    const storageMb = Math.max(0, Number(payload.storage_mb) || 0);

    const features = payload.features || {};
    const featureList = [
      features.production && "production",
      features.backups && "backups",
      features.zenoh && "zenoh",
    ]
      .filter(Boolean)
      .join(", ") || "none";

    // Log for Vercel logs (queryable)
    console.log(
      JSON.stringify({
        type: "telemetry_heartbeat",
        instance_id: instanceId,
        version,
        os,
        arch,
        uptime_secs: uptimeSecs,
        user_count: userCount,
        total_memories: totalMemories,
        storage_mb: storageMb,
        features: featureList,
        timestamp: new Date().toISOString(),
      })
    );

    // Notify via Telegram (plain text — no Markdown to avoid parse failures).
    // At most one notification per instance per hour: heartbeats are logged
    // above regardless, so dedupe only throttles the channel, not the data.
    const tgLimit = rateLimit(`telemetry:tg:${instanceId}`, 1, 3_600_000);
    if (tgLimit.allowed) {
      const msg = [
        "Shodh Heartbeat",
        `Instance: ${instanceId.slice(0, 8)}`,
        `Version: ${version} (${os}/${arch})`,
        `Uptime: ${formatUptime(uptimeSecs)}`,
        `Users: ${userCount} | Memories: ${totalMemories}`,
        `Storage: ${storageMb} MB | Features: ${featureList}`,
      ].join("\n");

      await sendToTelegram(msg);
    }

    return NextResponse.json({ status: "ok" });
  } catch {
    return NextResponse.json(
      { error: "Invalid payload" },
      { status: 400 }
    );
  }
}

// Health check for the telemetry endpoint
export async function GET() {
  return NextResponse.json({
    status: "ok",
    endpoint: "telemetry",
    accepts: "POST",
  });
}

import { NextRequest, NextResponse } from "next/server";
import Groq from "groq-sdk";
import { rateLimit, getClientIp, isValidIp, sanitizeLine, tooLarge } from "@/lib/ratelimit";

const groq = new Groq({
  apiKey: [REDACTED],
});

const MAX_BODY_BYTES = 200_000;
const MAX_MESSAGE_CHARS = 2_000;
const MAX_HISTORY_MESSAGES = 12;
const MAX_HISTORY_CONTENT_CHARS = 4_000;

const TELEGRAM_BOT_TOKEN = [REDACTED];
const TELEGRAM_CHAT_ID = process.env.TELEGRAM_CHAT_ID;

// Send message to Telegram
async function sendToTelegram(message: string) {
  if (!TELEGRAM_BOT_TOKEN || !TELEGRAM_CHAT_ID) {
    console.log("Telegram credentials missing");
    return;
  }

  try {
    const res = await fetch(`https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        chat_id: TELEGRAM_CHAT_ID,
        text: message,
      }),
    });
    const data = await res.json();
    if (!data.ok) {
      console.error("Telegram API error:", data);
    }
  } catch (error) {
    console.error("Telegram send error:", error);
  }
}

// Generate conversation summary
async function summarizeConversation(messages: ChatMessage[]): Promise<string> {
  if (messages.length < 2) return "";

  try {
    const completion = await groq.chat.completions.create({
      model: "llama-3.3-70b-versatile",
      messages: [
        {
          role: "system",
          content: "Summarize this customer conversation in 2-3 bullet points. Include: what they asked about, any contact info shared, and if they showed buying intent. Be concise.",
        },
        {
          role: "user",
          content: messages.map(m => `${m.role}: ${m.content}`).join("\n"),
        },
      ],
      temperature: 0.3,
      max_tokens: 200,
    });
    return completion.choices[0]?.message?.content || "";
  } catch {
    return "";
  }
}

